.clostrat-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2433;
    background: linear-gradient(168deg, #f4f1ea 0%, #eef0f1 60%, #e7ebef 100%);
    border-radius: 18px;
}

.clostrat-container * {
    box-sizing: border-box;
}

.clostrat-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #14233f 0%, #1d3a5f 55%, #25618f 100%);
    color: #f3f6fb;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(20, 35, 63, 0.32);
}

.clostrat-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.clostrat-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e8c887;
    background: rgba(232, 200, 135, 0.14);
    border: 1px solid rgba(232, 200, 135, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.clostrat-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cfddee;
}

.clostrat-context {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.clostrat-context-item {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(28, 36, 51, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.clostrat-ctx-margin { border-left: 5px solid #2e8b6f; }
.clostrat-ctx-cut { border-left: 5px solid #c0392b; }

.clostrat-ctx-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #14233f;
}

.clostrat-ctx-margin .clostrat-ctx-name { color: #1f7a60; }
.clostrat-ctx-cut .clostrat-ctx-name { color: #b03124; }

.clostrat-ctx-meta {
    font-size: 0.82rem;
    color: #5a6675;
    line-height: 1.4;
}

.clostrat-context-plus {
    align-self: center;
    font-size: 1.25rem;
    font-weight: 800;
    text-transform: uppercase;
    color: #25618f;
    letter-spacing: 1px;
}

.clostrat-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #43546b;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.clostrat-period-counter #currentDay,
.clostrat-period-counter #maxPeriods {
    font-weight: 800;
    color: #25618f;
}

.clostrat-round-name {
    background: rgba(37, 97, 143, 0.13);
    color: #1d4f78;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.clostrat-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a7320;
    background: rgba(232, 200, 135, 0.22);
    border: 1px solid rgba(232, 200, 135, 0.55);
    padding: 4px 12px;
    border-radius: 999px;
}

.clostrat-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.clostrat-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(28, 36, 51, 0.08);
    border-top: 4px solid #25618f;
}

.clostrat-card-impact { border-top-color: #2e8b6f; }
.clostrat-card-align { border-top-color: #25618f; }
.clostrat-card-eval { border-top-color: #7d5fc0; }
.clostrat-card-budget { border-top-color: #c79a3a; }

.clostrat-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #67748a;
}

.clostrat-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14233f;
    font-variant-numeric: tabular-nums;
}

.clostrat-card-impact .clostrat-value { color: #1f7a60; }
.clostrat-card-align .clostrat-value { color: #25618f; }
.clostrat-card-eval .clostrat-value { color: #6f4fb3; }
.clostrat-card-budget .clostrat-value { color: #b07f1f; }

.clostrat-sublabel {
    font-size: 0.76rem;
    color: #76849a;
    line-height: 1.35;
}

.clostrat-card-budget.clostrat-budget-cut { border-top-color: #c0392b; }
.clostrat-card-budget.clostrat-budget-cut .clostrat-value { color: #c0392b; }
.clostrat-card-budget.clostrat-budget-won { border-top-color: #2e8b6f; }
.clostrat-card-budget.clostrat-budget-won .clostrat-value { color: #1f7a60; }

.clostrat-board-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dfe4ea;
    color: #43546b;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.clostrat-board-bar #boardDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #c0392b;
    font-weight: 800;
}

.clostrat-board-bar.clostrat-board-mid #boardDisplay { color: #b07f1f; }
.clostrat-board-bar.clostrat-board-high #boardDisplay { color: #1f7a60; }

.clostrat-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #25618f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 36, 51, 0.07);
}

.clostrat-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.clostrat-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14233f;
    margin-bottom: 6px;
}

.clostrat-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4860;
}

.clostrat-briefing-text strong { color: #1d4f78; }
.clostrat-briefing-text em { color: #b07f1f; font-style: italic; }

.clostrat-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 36, 51, 0.07);
}

.clostrat-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14233f;
    border-bottom: 2px solid #e7ebef;
    padding-bottom: 8px;
}

.clostrat-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3a52;
    margin: 14px 0 6px;
}

.clostrat-container select,
.clostrat-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c6d0d9;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1c2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.clostrat-container select:focus,
.clostrat-container input[type="number"]:focus {
    outline: none;
    border-color: #25618f;
    box-shadow: 0 0 0 3px rgba(37, 97, 143, 0.16);
}

.clostrat-container select option {
    background-color: #ffffff;
    color: #1c2433;
}

.clostrat-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #25618f;
}

.clostrat-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #43546b;
    margin-top: 4px;
}

.clostrat-range-readout span#targetReadout,
.clostrat-range-readout span#targetEndReadout,
.clostrat-range-readout span#spendReadout {
    color: #25618f;
    font-weight: 800;
}

.clostrat-hint {
    font-size: 0.8rem;
    color: #76849a;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.clostrat-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.clostrat-container .btn-primary {
    background: linear-gradient(135deg, #1d3a5f 0%, #25618f 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(29, 58, 95, 0.32);
}

.clostrat-container .btn-primary:hover {
    filter: brightness(1.08);
}

.clostrat-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c6d0d9;
    color: #5a6675;
    background: transparent;
}

.clostrat-coach {
    background: linear-gradient(160deg, #14233f 0%, #1b3052 100%);
    color: #dde7f2;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(20, 35, 63, 0.26);
}

.clostrat-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e8c887;
    margin-bottom: 8px;
}

.clostrat-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.clostrat-coach-body strong { color: #8fd0bb; }
.clostrat-coach-body em { color: #e8c887; font-style: italic; }

.clostrat-history,
.clostrat-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 36, 51, 0.07);
}

.clostrat-history h3,
.clostrat-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14233f;
}

.clostrat-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4860;
}

.clostrat-container table#usfHistoryTable th {
    background: #eef2f6;
    color: #1d4f78;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d7e0e7;
}

.clostrat-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f4;
    color: #3a4860;
}

.clostrat-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fb;
}

.clostrat-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .clostrat-container {
        padding: 14px;
    }
    .clostrat-header h1 {
        font-size: 1.7rem;
    }
    .clostrat-context {
        flex-direction: column;
    }
    .clostrat-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .clostrat-value {
        font-size: 2rem;
    }
    .clostrat-clock {
        margin-left: 0;
    }
    .clostrat-period-counter {
        font-size: 0.88rem;
    }
    .clostrat-board-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .clostrat-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, clostrat-cm-*) ===== */
.clostrat-cm { color: #23303c; font-family: inherit; }
.clostrat-cm-generic { font-size: 15px; text-align: center; }
.clostrat-cm-scoreband { text-align: center; padding: 6px 0 14px; border-bottom: 1px solid rgba(35,48,60,0.12); margin-bottom: 16px; }
.clostrat-cm-score { font-size: 46px; font-weight: 700; line-height: 1; color: #3f6fb0; }
.clostrat-cm-score-max { font-size: 20px; font-weight: 500; color: #7c8896; margin-left: 2px; }
.clostrat-cm-tier { font-size: 20px; font-weight: 600; margin-top: 6px; color: #23303c; }
.clostrat-cm-caption { font-size: 11.5px; letter-spacing: .05em; text-transform: uppercase; color: #7c8896; margin-top: 4px; }
.clostrat-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 14px; }
.clostrat-cm-kpi { flex: 1 1 92px; min-width: 92px; background: rgba(63,111,176,0.07); border: 1px solid rgba(63,111,176,0.18); border-radius: 10px; padding: 10px 8px; text-align: center; }
.clostrat-cm-kpi-val { display: block; font-size: 20px; font-weight: 700; color: #23303c; }
.clostrat-cm-kpi-lbl { display: block; font-size: 11px; margin-top: 3px; color: #55636e; }
.clostrat-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-bottom: 14px; }
.clostrat-cm-chip { font-size: 12.5px; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.clostrat-cm-chip.is-met { background: rgba(46,143,107,0.14); border-color: rgba(46,143,107,0.42); color: #1f6e50; }
.clostrat-cm-chip.is-missed { background: rgba(197,74,74,0.12); border-color: rgba(197,74,74,0.4); color: #a23b3b; }
.clostrat-cm-insights { margin: 0; padding-left: 18px; }
.clostrat-cm-insights li { font-size: 13.5px; line-height: 1.5; color: #38434e; margin-bottom: 7px; }

