(function() {
    'use strict';

    class CloStrategicAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `L&D Goes Strategic`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Lumière Industrielle SA).
            this.BUDGET = 4.2;          // €4.2M L&D annual budget
            this.CUT = 1.4;             // €1.4M proposed cut (one-third)
            this.PRIZE = 11;            // ≈ €11M annual margin upside (20% revenue shift)
            this.WINRATE_START = 18;    // services win-rate now (%)
            this.WINRATE_TARGET = 35;   // board target (%)
            this.GAP = 17;              // 18 -> 35 = 17 points
            this.START_ALIGN = 28;      // day-1 strategic alignment
            this.START_BOARD = 35;      // day-1 CFO confidence

            // The fully-aligned target answers.
            this.TRUE_GOAL = `winrate`;
            this.TRUE_LADDER = `results`;
            this.TRUE_ATTR = `cohort`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    impact: 0,                       // €M business margin credibly attributed
                    align: this.START_ALIGN,         // strategic alignment (0–100)
                    evalLevel: 1,                    // Kirkpatrick level reached (1–4)
                    budget: this.BUDGET,             // €M secured for next cycle
                    board: this.START_BOARD,         // CFO confidence (0–100)
                    spend: 0,                         // €M committed to the program
                    winTarget: this.WINRATE_START + 3, // win-rate level the CLO put their name to
                    // Sticky, run-defining penalty flags (gate the top verdict).
                    activityGoalRun: false,          // anchored to an activity goal, not a business number
                    classroomDefault: false,         // over-invested in expensive low-scale ILT
                    happySheetRun: false,            // measurement stopped at reaction/learning
                    noAttribution: false,            // claimed credit with no control group
                    concededCut: false,              // accepted (part of) the €1.4M cut
                    overBudget: false,               // program design blew the €4.2M budget
                    impactCap: this.PRIZE,           // moving ceiling on creditable impact
                    impactHistory: [0],
                    alignHistory: [this.START_ALIGN],
                    boardHistory: [this.START_BOARD],
                    evalHistory: [1],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the five classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    goal: `completion`,
                    capability: `generic`,
                    catalogue: `keep`,
                    target: 3,
                    mix: `classroom`,
                    coaching: `none`,
                    manager: `ignore`,
                    spend: 5.0,
                    ladder: `reaction`,
                    leading: `activity`,
                    attribution: `claim`,
                    roi: `none`,
                    leadCase: `activity`,
                    budgetMove: `concede`,
                    sponsor: `nothing`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const go = document.getElementById(`goalInput`);
                const ca = document.getElementById(`capabilityInput`);
                const ct = document.getElementById(`catalogueInput`);
                const tg = document.getElementById(`targetInput`);
                if (go) decisions.goal = go.value;
                if (ca) decisions.capability = ca.value;
                if (ct) decisions.catalogue = ct.value;
                if (tg) decisions.target = parseInt(tg.value, 10);
                if (!Number.isFinite(decisions.target) || decisions.target < 0 || decisions.target > 17) {
                    warn(`warn_target_range`); return false;
                }
            } else if (round === 2) {
                const mx = document.getElementById(`mixInput`);
                const co = document.getElementById(`coachingInput`);
                const mg = document.getElementById(`managerInput`);
                const sp = document.getElementById(`spendInput`);
                if (mx) decisions.mix = mx.value;
                if (co) decisions.coaching = co.value;
                if (mg) decisions.manager = mg.value;
                if (sp) decisions.spend = parseFloat(sp.value);
                if (!Number.isFinite(decisions.spend) || decisions.spend < 1 || decisions.spend > 6) {
                    warn(`warn_spend_range`); return false;
                }
            } else if (round === 3) {
                const la = document.getElementById(`ladderInput`);
                const le = document.getElementById(`leadingInput`);
                const at = document.getElementById(`attributionInput`);
                const ro = document.getElementById(`roiInput`);
                if (la) decisions.ladder = la.value;
                if (le) decisions.leading = le.value;
                if (at) decisions.attribution = at.value;
                if (ro) decisions.roi = ro.value;
                if (![`reaction`, `learning`, `behavior`, `results`].includes(decisions.ladder)) {
                    warn(`warn_ladder`); return false;
                }
            } else if (round === 4) {
                const lc = document.getElementById(`leadCaseInput`);
                const bm = document.getElementById(`budgetMoveInput`);
                const so = document.getElementById(`sponsorInput`);
                const cv = document.getElementById(`convictionInput`);
                if (lc) decisions.leadCase = lc.value;
                if (bm) decisions.budgetMove = bm.value;
                if (so) decisions.sponsor = so.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let alignDelta = 0, boardDelta = 0, impactDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Find the business goal (Common Error 1: activity-based goals).
                switch (d.goal) {
                    case `winrate`:
                        alignDelta += 34; boardDelta += 14; coachKey = `coach_r1_winrate`;
                        break;
                    case `completion`:
                        ds.activityGoalRun = true; alignDelta += 2; boardDelta -= 8; coachKey = `coach_r1_completion`;
                        break;
                    case `satisfaction`:
                        ds.activityGoalRun = true; alignDelta += 1; boardDelta -= 8; coachKey = `coach_r1_satisfaction`;
                        break;
                    case `broad`:
                        ds.activityGoalRun = true; alignDelta += 4; boardDelta -= 5; coachKey = `coach_r1_broad`;
                        break;
                }

                switch (d.capability) {
                    case `consultative`: alignDelta += 16; boardDelta += 6; break;
                    case `compliance`: alignDelta += 2; boardDelta -= 3; if (!ds.activityGoalRun) coachKey = `coach_r1_compliance`; break;
                    case `generic`: alignDelta -= 2; boardDelta -= 4; if (!ds.activityGoalRun) coachKey = `coach_r1_generic`; break;
                }

                switch (d.catalogue) {
                    case `prune`: alignDelta += 8; boardDelta += 5; break;
                    case `add`: alignDelta -= 2; boardDelta -= 3; break;
                    case `keep`: alignDelta -= 4; boardDelta -= 4; break;
                }

                // The win-rate target the CLO commits to. A credible stretch builds
                // confidence; lowballing reads as no ambition, over-promising as fantasy.
                ds.winTarget = this.WINRATE_START + d.target;
                if (d.target >= 12 && d.target <= 15) { boardDelta += 6; alignDelta += 4; }
                else if (d.target >= 16) { boardDelta -= 5; coachKey = `coach_r1_overpromise`; }
                else if (d.target <= 4) { boardDelta -= 4; alignDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r1_lowball`; }
                else { boardDelta += 2; }

                summaryKey = (d.goal === `winrate` && d.capability === `consultative` && d.catalogue === `prune`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Design the program & choose modalities (Common Error 2: classroom default).
                ds.spend = d.spend;
                const overBudget = d.spend > this.BUDGET;
                ds.overBudget = overBudget;

                switch (d.mix) {
                    case `balanced`:
                        alignDelta += 10; boardDelta += 8; impactDelta += 3.0; coachKey = `coach_r2_balanced`;
                        break;
                    case `classroom`:
                        ds.classroomDefault = true; alignDelta -= 4; boardDelta -= 6; impactDelta += 0.6; coachKey = `coach_r2_classroom`;
                        break;
                    case `digital`:
                        alignDelta += 2; boardDelta += 1; impactDelta += 1.0; coachKey = `coach_r2_digital`;
                        break;
                }

                switch (d.coaching) {
                    case `frontline`: impactDelta += 2.6; alignDelta += 6; boardDelta += 5; break;
                    case `everyone`: impactDelta += 0.8; boardDelta -= 4; if (d.spend < 6) ds.overBudget = true; coachKey = (d.mix === `classroom`) ? coachKey : `coach_r2_coachall`; break;
                    case `none`: impactDelta += 0.2; if (d.mix !== `classroom`) coachKey = `coach_r2_nocoach`; break;
                }

                switch (d.manager) {
                    case `reinforce`: impactDelta += 2.4; alignDelta += 6; boardDelta += 4; break;
                    case `inform`: impactDelta += 0.6; break;
                    case `ignore`: impactDelta -= 1.0; boardDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r2_nomanager`; break;
                }

                // Budget discipline: overspending undermines the budget case directly.
                if (ds.overBudget) {
                    boardDelta -= 9; impactDelta -= 1.0; coachKey = `coach_r2_overbudget`;
                } else if (d.spend <= 3.5 && d.mix === `balanced`) {
                    // Disciplined and effective — the board notices efficiency.
                    boardDelta += 4;
                }

                // The classroom-for-everyone trap: expensive, low-scale, low behavior change.
                if (d.mix === `classroom` && d.coaching !== `frontline`) {
                    ds.classroomDefault = true;
                }

                summaryKey = (d.mix === `balanced` && d.coaching === `frontline` && d.manager === `reinforce` && !ds.overBudget) ? `sum_r2_good` :
                             (d.mix === `classroom` ? `sum_r2_classroom` : `sum_r2_weak`);
            } else if (round === 3) {
                // Build the measurement case (Common Errors 3 & 5).
                const ladderMap = { reaction: 1, learning: 2, behavior: 3, results: 4 };
                const reached = ladderMap[d.ladder] || 1;
                ds.evalLevel = Math.max(ds.evalLevel, reached);

                switch (d.ladder) {
                    case `results`: alignDelta += 14; boardDelta += 12; impactDelta += 2.0; break;
                    case `behavior`: alignDelta += 8; boardDelta += 6; impactDelta += 1.0; break;
                    case `learning`: ds.happySheetRun = true; alignDelta += 2; boardDelta -= 3; coachKey = `coach_r3_learning`; break;
                    case `reaction`: ds.happySheetRun = true; alignDelta -= 3; boardDelta -= 9; coachKey = `coach_r3_reaction`; break;
                }

                switch (d.leading) {
                    case `skillbehavior`: alignDelta += 8; boardDelta += 6; impactDelta += 0.8; break;
                    case `reaction`: ds.happySheetRun = true; boardDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r3_leadreaction`; break;
                    case `activity`: ds.happySheetRun = true; boardDelta -= 5; alignDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r3_leadactivity`; break;
                }

                switch (d.attribution) {
                    case `cohort`: alignDelta += 10; boardDelta += 13; impactDelta += 2.0; break;
                    case `survey`: ds.noAttribution = true; boardDelta -= 4; impactDelta += 0.3; if (coachKey === `coach_default`) coachKey = `coach_r3_survey`; break;
                    case `claim`: ds.noAttribution = true; boardDelta -= 10; impactDelta -= 0.5; coachKey = `coach_r3_claim`; break;
                }

                switch (d.roi) {
                    case `grounded`: alignDelta += 6; boardDelta += 8; impactDelta += 1.0; break;
                    case `vanity`: boardDelta -= 6; coachKey = (d.attribution === `cohort`) ? coachKey : `coach_r3_vanity`; break;
                    case `none`: boardDelta -= 5; alignDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r3_noroi`; break;
                }

                if (d.ladder === `results` && d.attribution === `cohort` && d.leading === `skillbehavior` && d.roi === `grounded`) {
                    coachKey = `coach_r3_evidence`;
                }

                summaryKey = (d.ladder === `results` && d.leading === `skillbehavior` && d.attribution === `cohort` && d.roi === `grounded`) ? `sum_r3_good` :
                             (ds.happySheetRun ? `sum_r3_happysheet` :
                             (ds.noAttribution ? `sum_r3_noattr` : `sum_r3_weak`));
            } else if (round === 4) {
                // Defend the budget to the board (Common Error 4: conceding the cut).
                switch (d.leadCase) {
                    case `business`: alignDelta += 8; boardDelta += 12; impactDelta += 1.0; coachKey = `coach_r4_business`; break;
                    case `effort`: boardDelta -= 6; coachKey = `coach_r4_effort`; break;
                    case `activity`: boardDelta -= 9; alignDelta -= 3; coachKey = `coach_r4_activity`; break;
                }

                switch (d.budgetMove) {
                    case `defend`:
                        ds.budget = this.BUDGET; boardDelta += 10; alignDelta += 4; coachKey = `coach_r4_defend`;
                        break;
                    case `invest`:
                        // Arguing for more only lands with a real evidenced case behind it.
                        if (!ds.activityGoalRun && !ds.happySheetRun && !ds.noAttribution && ds.board >= 60) {
                            ds.budget = this.BUDGET + 0.8; boardDelta += 12; alignDelta += 5; coachKey = `coach_r4_invest`;
                        } else {
                            ds.budget = this.BUDGET; boardDelta -= 4; coachKey = `coach_r4_investweak`;
                        }
                        break;
                    case `split`:
                        ds.concededCut = true; ds.budget = this.BUDGET - (this.CUT / 2); boardDelta += 2; coachKey = `coach_r4_split`;
                        break;
                    case `concede`:
                        ds.concededCut = true; ds.budget = this.BUDGET - this.CUT; boardDelta -= 2; coachKey = `coach_r4_concede`;
                        break;
                }

                switch (d.sponsor) {
                    case `kpis`: alignDelta += 8; boardDelta += 8; impactDelta += 0.8; break;
                    case `happy`: ds.happySheetRun = true; boardDelta -= 5; if (coachKey === `coach_default`) coachKey = `coach_r4_happy`; break;
                    case `nothing`: boardDelta -= 6; alignDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r4_nothing`; break;
                }

                if (d.conviction >= 60) { boardDelta += 4; alignDelta += 2; }
                else if (d.conviction <= 25) { boardDelta -= 4; }

                if (d.leadCase === `business` && d.budgetMove !== `concede` && d.budgetMove !== `split` && d.sponsor === `kpis`) {
                    coachKey = `coach_r4_strong`;
                }

                summaryKey = (d.leadCase === `business` && (d.budgetMove === `defend` || d.budgetMove === `invest`) && d.sponsor === `kpis`) ? `sum_r4_good` :
                             (ds.concededCut ? `sum_r4_conceded` : `sum_r4_weak`);
            }

            // ---- Apply alignment & board deltas (clamped 0–100). ----
            ds.align = Math.max(0, Math.min(100, Math.round((ds.align + alignDelta) * 10) / 10));
            ds.board = Math.max(0, Math.min(100, Math.round(ds.board + boardDelta)));

            // ---- STICKY CAPS: the headline anti-patterns cannot reach a strong score. ----
            // A program tied to an activity goal cannot be strategically aligned, period.
            if (ds.activityGoalRun) ds.align = Math.min(ds.align, 45);
            // Stopping at happy-sheets caps how high the alignment story can read.
            if (ds.happySheetRun) ds.align = Math.min(ds.align, 62);

            // ---- Business impact: only what is credibly attributable counts. ----
            ds.impact = Math.max(0, Math.round((ds.impact + impactDelta) * 10) / 10);

            // The creditable-impact CEILING is gated by the flags. This is what stops a
            // strong later round from washing out an early headline error.
            let cap = this.PRIZE; // €11M theoretical max
            if (ds.activityGoalRun) cap = Math.min(cap, 2);   // no business anchor -> almost nothing is creditable
            if (ds.classroomDefault) cap = Math.min(cap, 4);  // expensive, low behavior change -> little capability built
            if (ds.noAttribution) cap = Math.min(cap, 3);     // cannot prove the lift was the program
            if (ds.happySheetRun) cap = Math.min(cap, 3.5);   // never measured business results
            if (ds.overBudget) cap = Math.min(cap, cap - 1);  // value net of an over-budget design
            ds.impactCap = cap;
            ds.impact = Math.min(ds.impact, cap);
            ds.impact = Math.round(ds.impact * 10) / 10;

            ds.impactHistory.push(ds.impact);
            ds.alignHistory.push(ds.align);
            ds.boardHistory.push(ds.board);
            ds.evalHistory.push(ds.evalLevel);

            // ---- Persist composite where the grading/reporting layer reads it ----
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = ds.performance || {};
            ds.performance.overallScore = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                overallScore: _score,
                score: _score,
                impact: ds.impact,
                impactDelta: Math.round(impactDelta * 10) / 10,
                align: ds.align,
                alignDelta: Math.round(alignDelta * 10) / 10,
                evalLevel: ds.evalLevel,
                budget: ds.budget,
                board: ds.board,
                concededCut: ds.concededCut,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _boardLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 70) return t(`board_high`);
            if (v >= 45) return t(`board_mid`);
            return t(`board_low`);
        }

        _evalLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const n = Math.round(Number(v));
            const names = { 1: t(`eval_l1`), 2: t(`eval_l2`), 3: t(`eval_l3`), 4: t(`eval_l4`) };
            return `${n} · ${names[n] || names[1]}`;
        }

        _fmtM(v) {
            // Locale-aware €M with one decimal: en "€4.2M", es "4,2 M€".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            if (lang === `es`) return s.replace(`.`, `,`) + ` M€`;
            return `€${s}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`impactDisplay`, `domainState.impact`, (v) => self._fmtM(Number(v)));
            uiManager.bind(`alignDisplay`, `domainState.align`, (v) => `${Math.round(Number(v))}`);
            uiManager.bind(`evalDisplay`, `domainState.evalLevel`, (v) => self._evalLabel(v));

            uiManager.bind(`budgetDisplay`, `domainState.budget`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.clostrat-card-budget`);
                if (card) {
                    card.classList.toggle(`clostrat-budget-cut`, n < self.BUDGET - 0.01);
                    card.classList.toggle(`clostrat-budget-won`, n >= self.BUDGET - 0.01 && (window.mySimulation.state.currentPeriod > 4 || window.mySimulation.state.domainState.budget !== self.BUDGET || window.mySimulation.state.currentPeriod >= 5));
                }
                return self._fmtM(n);
            });

            uiManager.bind(`boardDisplay`, `domainState.board`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.clostrat-board-bar`);
                if (bar) {
                    bar.classList.toggle(`clostrat-board-high`, n >= 70);
                    bar.classList.toggle(`clostrat-board-mid`, n >= 45 && n < 70);
                }
                return self._boardLabel(n);
            });

            // Win-rate target slider readout (Round 1).
            const tg = document.getElementById(`targetInput`);
            const tgReadout = document.getElementById(`targetReadout`);
            const tgEnd = document.getElementById(`targetEndReadout`);
            if (tg && tgReadout) {
                const sync = () => {
                    tgReadout.textContent = tg.value;
                    if (tgEnd) tgEnd.textContent = (self.WINRATE_START + parseInt(tg.value, 10));
                };
                sync();
                tg.addEventListener(`input`, sync);
            }

            // Program-spend slider readout (Round 2).
            const sp = document.getElementById(`spendInput`);
            const spReadout = document.getElementById(`spendReadout`);
            if (sp && spReadout) {
                const syncSp = () => { spReadout.textContent = parseFloat(sp.value).toFixed(1); };
                syncSp();
                sp.addEventListener(`input`, syncSp);
            }
        }

        getChartConfig() {
            return {
                cloStrategyChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_align`) : `Strategic alignment (0–100)`,
                                data: [],
                                borderColor: `#25618f`,
                                backgroundColor: `rgba(37,97,143,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#25618f`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_board`) : `CFO confidence (0–100)`,
                                data: [],
                                borderColor: `#c79a3a`,
                                backgroundColor: `rgba(199,154,58,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c79a3a`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_impact`) : `Business impact (€M ×9)`,
                                data: [],
                                borderColor: `#2e8b6f`,
                                backgroundColor: `rgba(46,139,111,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2e8b6f`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#43546b`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#76849a` }, grid: { color: `rgba(28,36,51,0.06)` },
                                title: { display: true, text: `0–100`, color: `#76849a` }
                            },
                            x: {
                                ticks: { color: `#76849a` }, grid: { color: `rgba(28,36,51,0.04)` },
                                title: { display: true, text: `Round`, color: `#76849a` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.alignHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Impact is €M (0–11) — scale ×9 (≈ ×100/11) to share the 0–100 axis.
            const impactScaled = ds.impactHistory.map((v) => Math.round(v * 9));
            return {
                cloStrategyChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.alignHistory.map((v) => Math.round(v)) },
                        { data: ds.boardHistory.map((v) => Math.round(v)) },
                        { data: impactScaled }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 completion formula, single source of truth, persisted every period so the
            // grading/analytics/LTI layer (domainState.performance.overallScore then top-level
            // score) receives a number instead of null -> 0.0.
            const impact = Math.round(ds.impact * 10) / 10;
            const align = Math.round(ds.align);
            const evalLevel = Math.round(ds.evalLevel);
            const budget = Math.round(ds.budget * 10) / 10;
            const board = Math.round(ds.board);
            const budgetDefended = budget >= this.BUDGET - 0.01;
            const impactScore = (impact / this.PRIZE) * 100;
            const evalScore = ((evalLevel - 1) / 3) * 100;
            const budgetScore = budgetDefended ? 100 : (budget / this.BUDGET) * 100;
            return Math.round(impactScore * 0.34 + align * 0.24 + board * 0.18 + evalScore * 0.12 + budgetScore * 0.12);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const impact = Math.round(ds.impact * 10) / 10;
            const align = Math.round(ds.align);
            const evalLevel = Math.round(ds.evalLevel);
            const budget = Math.round(ds.budget * 10) / 10;
            const board = Math.round(ds.board);
            const budgetDefended = budget >= this.BUDGET - 0.01;

            // Composite (0–100): impact carries the most weight, then alignment,
            // CFO confidence, evaluation maturity and the budget outcome.
            const composite = this._composite(ds);

            const anyFlag = ds.activityGoalRun || ds.classroomDefault || ds.happySheetRun || ds.noAttribution || ds.concededCut;

            const aligned = align >= 75;
            const evidenced = evalLevel === 4 && !ds.noAttribution;
            const fundedWell = budgetDefended && !ds.concededCut;
            const impactStrong = impact >= 6;
            const boardWon = board >= 70;

            let pattern = `mixed`;
            if (ds.activityGoalRun) pattern = `activity`;
            else if (ds.classroomDefault) pattern = `classroom`;
            else if (ds.happySheetRun) pattern = `happysheet`;
            else if (ds.noAttribution) pattern = `noattr`;
            else if (ds.concededCut) pattern = `conceded`;
            else if (impactStrong && aligned && evidenced && fundedWell) pattern = `strategic`;

            // Top verdict is GATED by every sticky flag AND the real thresholds.
            let performance = `Cost Center`, performanceKey = `grade_costcenter`;
            if (!anyFlag && impactStrong && aligned && evidenced && fundedWell && boardWon && composite >= 80) {
                performance = `Strategic Partner`; performanceKey = `grade_strategic`;
            } else if (!anyFlag && impact >= 4 && align >= 65 && evalLevel >= 3 && budgetDefended && composite >= 62) {
                performance = `Business Case Made`; performanceKey = `grade_businesscase`;
            } else if (ds.concededCut && !ds.activityGoalRun && impact >= 3) {
                performance = `Conceded the Cut`; performanceKey = `grade_conceded`;
            } else if (ds.activityGoalRun) {
                performance = `Activity Trap`; performanceKey = `grade_activity`;
            } else if (ds.happySheetRun) {
                performance = `Happy-Sheet Trap`; performanceKey = `grade_happysheet`;
            } else if (ds.noAttribution) {
                performance = `Attribution Gap`; performanceKey = `grade_noattr`;
            } else if (ds.classroomDefault) {
                performance = `Classroom Default`; performanceKey = `grade_classroom`;
            } else if (composite >= 50) {
                performance = `Partial Case`; performanceKey = `grade_partial`;
            }

            const insights = [];
            if (performance === `Strategic Partner`) insights.push(window.mySimulation.t(`insight_strategic`));
            else if (pattern === `activity`) insights.push(window.mySimulation.t(`insight_activity`));
            else if (pattern === `classroom`) insights.push(window.mySimulation.t(`insight_classroom`));
            else if (pattern === `happysheet`) insights.push(window.mySimulation.t(`insight_happysheet`));
            else if (pattern === `noattr`) insights.push(window.mySimulation.t(`insight_noattr`));
            else if (pattern === `conceded`) insights.push(window.mySimulation.t(`insight_conceded`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.concededCut && pattern !== `conceded`) insights.push(window.mySimulation.t(`insight_conceded`));
            if (ds.classroomDefault && pattern !== `classroom`) insights.push(window.mySimulation.t(`insight_classroom_note`));
            if (evalLevel < 3) insights.push(window.mySimulation.t(`insight_eval_low`));
            if (impactStrong && aligned && evidenced && !budgetDefended) insights.push(window.mySimulation.t(`insight_gave_away`));

            return {
                impact: impact,
                align: align,
                evalLevel: evalLevel,
                budget: budget,
                board: board,
                budgetDefended: budgetDefended,
                aligned: aligned,
                evidenced: evidenced,
                impactStrong: impactStrong,
                pattern: pattern,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (!summary || typeof summary.composite !== `number`) {
                return `<div class="clostrat-cm"><p class="clostrat-cm-generic">${t(`cm_generic`)}</p></div>`;
            }
            const tier = summary.performanceKey ? t(summary.performanceKey) : (summary.performance || ``);
            const kpi = (labelKey, valStr) =>
                `<div class="clostrat-cm-kpi"><span class="clostrat-cm-kpi-val">${valStr}</span>`
                + `<span class="clostrat-cm-kpi-lbl">${t(labelKey)}</span></div>`;
            const chip = (ok, labelKey) =>
                `<span class="clostrat-cm-chip ${ok ? `is-met` : `is-missed`}">`
                + `${ok ? `✓` : `✗`} ${t(labelKey)}</span>`;
            const insights = (summary.insights || []).map((x) => `<li>${x}</li>`).join(``);
            return ``
                + `<div class="clostrat-cm">`
                +   `<div class="clostrat-cm-scoreband">`
                +     `<div class="clostrat-cm-score">${summary.composite}<span class="clostrat-cm-score-max">/100</span></div>`
                +     `<div class="clostrat-cm-tier">${tier}</div>`
                +     `<div class="clostrat-cm-caption">${t(`cm_caption`)}</div>`
                +   `</div>`
                +   `<div class="clostrat-cm-kpis">`
                +     kpi(`cm_kpi_impact`, self._fmtM(summary.impact))
                +     kpi(`cm_kpi_align`, String(Math.round(summary.align)))
                +     kpi(`cm_kpi_eval`, `L` + String(Math.round(summary.evalLevel)))
                +     kpi(`cm_kpi_budget`, self._fmtM(summary.budget))
                +     kpi(`cm_kpi_board`, String(Math.round(summary.board)))
                +   `</div>`
                +   `<div class="clostrat-cm-chips">`
                +     chip(summary.impactStrong, `cm_chip_impact`)
                +     chip(summary.aligned, `cm_chip_align`)
                +     chip(summary.evidenced, `cm_chip_eval`)
                +     chip(summary.budgetDefended, `cm_chip_budget`)
                +   `</div>`
                +   (insights ? `<ul class="clostrat-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.activityGoalRun) return window.mySimulation.t(`hint_activity`);
            if (ds.classroomDefault) return window.mySimulation.t(`hint_classroom`);
            if (ds.noAttribution && state.currentPeriod >= 3) return window.mySimulation.t(`hint_noattr`);
            if (ds.happySheetRun && state.currentPeriod >= 3) return window.mySimulation.t(`hint_happysheet`);
            if (ds.concededCut) return window.mySimulation.t(`hint_conceded`);
            if (ds.board < 45 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_board`);
            if (ds.align >= 75 && ds.board >= 70 && ds.impact >= 6) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.impact`, label: `Impact`, i18nKey: `col_impact`, formatter: (v) => self._fmtM(Number(v)) },
                { key: `results.align`, label: `Alignment`, i18nKey: `col_align`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.evalLevel`, label: `Eval`, i18nKey: `col_eval`, formatter: (v) => `L${Math.round(v)}` },
                { key: `results.budget`, label: `Budget`, i18nKey: `col_budget`, formatter: (v) => self._fmtM(Number(v)) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
